[$base,$custom,$total,$saved] = totals($items);
?>
<section class="wrap section"><div class="page-title"><span class="eyebrow">FINAL WHISTLE</span><h1>Checkout<span class="dot">.</span></h1></div><?php if(!$items): ?><div class="empty">Your cart is empty.</div><?php else: ?><div class="columns"><form method="post" class="form checkout"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="checkout"><h3>DELIVERY DETAILS</h3><label>FULL NAME<input name="name" value="<?=e(current_user()['name'])?>" required></label><div class="two"><label>EMAIL<input type="email" name="email"></label><label>PHONE<input name="phone" required></label></div><label>ADDRESS<textarea name="address" required></textarea></label><div class="two"><label>TOWNSHIP<input name="township"></label><label>CITY<input name="city"></label></div><h3>PAYMENT</h3><select name="payment_method"><option value="cod">Cash on delivery</option><option value="kbzpay">KBZPay (manual confirmation)</option><option value="wavepay">WavePay (manual confirmation)</option><option value="ayapay">AYA Pay (manual confirmation)</option></select><small>Digital payments need store confirmation.</small><label>ORDER NOTE<textarea name="note"></textarea></label><button class="btn lime full">PLACE ORDER · <?=price($total)?> ↗</button></form><aside class="summary"><h3>YOUR ORDER</h3><?php foreach($items as $item): ?><p><span><?=e($item['name'])?> · <?=e($item['size'])?> × <?=$item['quantity']?></span><b><?=price($item['price']*$item['quantity'])?></b></p><?php endforeach; ?><p><span>Discount saved</span><b><?=price($saved)?></b></p><?php if($custom): ?><p><span>Personalization</span><b><?=price($custom)?></b></p><?php endif; ?><p class="total"><span>Total</span><b><?=price($total)?></b></p></aside></div><?php endif; ?></section>
